PACKAGE_ROOT = package_root()


def _normalize_relative_pythonpath() -> None:
    """Keep child adapter processes on this package when their cwd changes."""
    value = os.environ.get("PYTHONPATH")
    if not value:
        return
    source_root = str(PACKAGE_ROOT.parent)
    entries = value.split(os.pathsep)
    normalized = [source_root if entry == "src" else entry for entry in entries]
    if normalized != entries:
        os.environ["PYTHONPATH"] = os.pathsep.join(normalized)


_normalize_relative_pythonpath()
