def configure_modal_platform(
    *,
    host: Any,
    installed_skills: Iterable[str],
    environment_resolver: Callable[[str, str], bool],
    package_resolver: Callable[[str], bool] | None = None,
    render_smoke: Callable[[str], str | None] | None = None,
    wait_for_notification: Callable[[], Mapping[str, Any]] | None = None,
    promote_artifacts: Callable[..., Any] | None = None,
    details_reader: Callable[[Mapping[str, str]], Any] | None = None,
    identity_reader: Callable[[], Any] | None = None,
) -> None:
    """Bind free Modal preflight capabilities from the Claude Science kernel.

    The callbacks deliberately stay explicit. A missing capability fails the
    preflight before ``submit_job`` rather than treating a configuration name
    as proof that the user's Modal account can use it.

    ``details_reader`` is the kernel's ``compute_details`` tool. The preflight
    subcommand calls it once, in read mode, to measure Modal authorization. An
    unbound reader leaves authorization not measured, which blocks a paid
    Modal campaign.

    ``identity_reader`` is a zero-argument callable over the provider
    ``token_info`` read, which reports ``workspace_name``. It is the only read
    that names the workspace, because a ``compute_details`` reply carries the
    per-workspace environment ledger and never the name. The preflight calls it
    only when the ledger names no workspace. Leaving it unbound keeps the
    workspace check failing closed.
    """
    # None of these is a Claude Science kernel global. A frame that reads one out
    # of globals() gets its own fallback, and the fallback is usually a callable,
    # so the mistake used to surface as "'function' object is not iterable" raised
    # by tuple() below, naming neither the parameter nor the cause. Check first, so
    # a rejected call also leaves an existing binding alone.
    if isinstance(installed_skills, str) or not isinstance(installed_skills, Iterable):
        raise TypeError(
            "configure_modal_platform installed_skills must be a sequence of "
            f"skill-name strings, not {type(installed_skills).__name__}"
        )
    skill_names = tuple(installed_skills)
    if not all(isinstance(name, str) for name in skill_names):
        raise TypeError(
            "configure_modal_platform installed_skills must be a sequence of "
            "skill-name strings"
        )
    if not callable(environment_resolver):
        raise TypeError(
            "configure_modal_platform environment_resolver must be callable, not "
            f"{type(environment_resolver).__name__}"
        )
    for parameter, capability in (
        ("package_resolver", package_resolver),
        ("render_smoke", render_smoke),
    ):
        if capability is None:
            continue
        if not callable(capability):
            raise TypeError(
                f"configure_modal_platform {parameter} must be callable, not "
                f"{type(capability).__name__}"
            )
    _MODAL_PLATFORM_CONTEXT.clear()
    _MODAL_PLATFORM_CONTEXT.update(
        {
            "host": host,
            "installed_skills": skill_names,
            "package_resolver": package_resolver,
            "environment_resolver": environment_resolver,
            "render_smoke": render_smoke,
            "wait_for_notification": wait_for_notification,
            "promote_artifacts": promote_artifacts,
            "details_reader": details_reader,
            "identity_reader": identity_reader,
        }
    )


def configure_runpod_platform(
    *,
    host: Any,
    account_reader: Callable[[Mapping[str, str]], Any],
) -> None:
    """Bind the native RunPod host and its read-only authorization capability.

    ``account_reader`` may be the Claude Science provider read or a wrapper
    around an environment-backed client.  Binding it performs no provider
    operation; preflight invokes only its read mode, and dispatch remains
    separately approval- and spend-gated.
    """
    _RUNPOD_PLATFORM_CONTEXT.clear()
    _RUNPOD_PLATFORM_CONTEXT.update(
        {"host": host, "account_reader": account_reader}
    )


def configure_lambda_platform(
    *,
    host: Any,
    account_reader: Callable[[Mapping[str, str]], Any],
) -> None:
    """Bind the native Lambda Cloud host and read-only account capability."""
    _LAMBDA_PLATFORM_CONTEXT.clear()
    _LAMBDA_PLATFORM_CONTEXT.update(
        {"host": host, "account_reader": account_reader}
    )


def bind_native_provider_submission(
    plan_path: Path,
    *,
    stage_id: str,
    job_id: str,
    run_root_override: Path | None = None,
) -> dict[str, Any]:
    """Recover an ambiguous native-provider acceptance without resubmitting."""
    plan = load_json(plan_path.resolve())
    run_root = (run_root_override or Path(plan["runtime"]["run_root"])).resolve()
    pending_path = run_root / "artifacts" / "native-provider" / f"{stage_id}.json"
    if not pending_path.is_file():
        return {"ok": False, "errors": [f"no pending native submission for {stage_id}"]}
    pending = load_json(pending_path)
    provider_id = pending.get("provider_id")
    platform_module = {
        "runpod": runpod_platform,
        "lambda": lambda_platform,
    }.get(provider_id)
    if platform_module is None:
        return {"ok": False, "errors": [f"unsupported pending provider: {provider_id!r}"]}
    submission_id = pending.get("submission_id")
    try:
        row = platform_module.bind_uncertain_submission(
            run_root,
            plan=plan,
            submission_id=submission_id,
            job_id=job_id,
        )
    except Exception as exc:
        return {"ok": False, "errors": [f"bind refused: {type(exc).__name__}: {exc}"]}
    pending.update({"ambiguous": False, "job_id": job_id, "submission": row})
    write_json(pending_path, pending)
    return {
        "ok": True,
        "stage_id": stage_id,
        "provider_id": provider_id,
        "job_id": job_id,
        "pending_record": str(pending_path),
        "next": "resume the Binder run to attach, harvest, validate, settle, and clean up",
    }


